79	/** A base class that encapsulates an NVCVResourceAllocator struct
80	 *
81	 * This class is a convenience wrapper around NVCVResourceAllocator. The derived classes expose
82	 * additional functionality, specific to the resource type being allocated.
83	 *
84	 * @warning ResourceAllocator does not own the context object pointed to by cdata().ctx.
85	 *          The destruction of ResourceAllocator does not call the cleanup function.
86	 */
87	class ResourceAllocator
88	{
89	public:
90	    ResourceAllocator() = default;
91	
92	    explicit ResourceAllocator(const NVCVResourceAllocator &alloc)
93	        : m_data(alloc)
94	    {
95	    }
96	
97	    /** Returns the underlying allocator descriptor
98	     */
99	    const NVCVResourceAllocator &cdata() const &
100	    {
101	        return m_data;
102	    }
103	
104	    /** Returns the underlying allocator descriptor
105	     */
106	    NVCVResourceAllocator cdata() &&
107	    {
108	        return m_data;
109	    }
110	
111	    /** Casts the resource allocator to a compatible type.
112	     */
113	    template<typename Derived>
114	    Derived cast() const
115	    {
116	        static_assert(std::is_base_of<ResourceAllocator, Derived>::value,
117	                      "The requested type does not inherit from ResourceAllocator");
118	        static_assert(std::is_constructible<Derived, NVCVResourceAllocator>::value,
119	                      "The requested type must be constructible from NVCVResourceAllocator");
120	        return Derived(m_data);
121	    }
122	
123	    static constexpr bool IsCompatibleKind(NVCVResourceType)
124	    {
125	        return true;
126	    }
127	
128	protected:
129	    NVCVResourceAllocator &data() &
130	    {
131	        return m_data;
132	    }
133	
134	private:
135	    NVCVResourceAllocator m_data{};
136	};
