138	/** Encapculates a memory allocator (NVCV_RESOURCE_MEM_*)
139	 */
140	class MemAllocator : public ResourceAllocator
141	{
142	public:
143	    using ResourceAllocator::ResourceAllocator;
144	
145	    static constexpr int DEFAULT_ALIGN = alignof(std::max_align_t);
146	
147	    /** Calls the allocation function from the underlying descriptor
148	     */
149	    NVCVMemoryBuffer alloc(int64_t size, int32_t align = DEFAULT_ALIGN)
150	    {
151	        return data().res.mem.fnAlloc(data().ctx, size, align);
152	    }
153	
154	    /** Calls the deallocation function from the underlying descriptor
155	     */
156	    void free(NVCVMemoryBuffer ptr, int64_t size, int32_t align = DEFAULT_ALIGN) noexcept
157	    {
158	        data().res.mem.fnFree(data().ctx, ptr, size, align);
159	    }
160	
161	    template<typename T>
162	    void free(T *ptr, int64_t size, int32_t align = DEFAULT_ALIGN) noexcept
163	    {
164	        free(static_cast<NVCVMemoryBuffer>(static_cast<void *>(ptr)), size, align);
165	    }
166	
167	    static constexpr bool IsCompatibleKind(NVCVResourceType resType)
168	    {
169	        return resType == NVCV_RESOURCE_MEM_HOST || resType == NVCV_RESOURCE_MEM_HOST_PINNED
170	            || resType == NVCV_RESOURCE_MEM_CUDA;
171	    }
172	};
