222	/** Represents a reference to an allocator object.
223	 *
224	 * The allocator object defines functions for allocating various resources, including
225	 * different kinds of memory.
226	 *
227	 * A custom allocator can be created via `nvcv::CustomAllocator` helper class.
228	 */
229	class Allocator : public CoreResource<NVCVAllocatorHandle, Allocator>
230	{
231	public:
232	    using Base = CoreResource<NVCVAllocatorHandle, Allocator>;
233	
234	    using Base::Base;
235	    using Base::operator=;
236	
237	    Allocator(const Allocator &other)
238	        : Base(other)
239	    {
240	    }
241	
242	    Allocator(Allocator &&other) noexcept
243	        : Base(std::move(other))
244	    {
245	    }
246	
247	    Allocator &operator=(const Allocator &other)
248	    {
249	        Base::operator=(other);
250	        return *this;
251	    }
252	
253	    Allocator &operator=(Allocator &&other) noexcept
254	    {
255	        Base::operator=(std::move(other));
256	        return *this;
257	    }
258	
259	    ~Allocator()
260	    {
261	        reset();
262	    }
263	
264	    HostMemAllocator       hostMem() const;
265	    HostPinnedMemAllocator hostPinnedMem() const;
266	    CudaMemAllocator       cudaMem() const;
267	
268	    ResourceAllocator get(NVCVResourceType resType) const;
269	
270	    template<typename ResAlloc>
271	    ResAlloc get() const;
272	};
