274	///////////////////////////////////////////////
275	// Custom allocators
276	
277	/** Marshals a set of allocation/deallocation functions as NVCVResourceAllocator
278	 *
279	 * @note This class should not be used directly. Use one of the following typedefs:
280	 *       - CustomHostMemAllocator
281	 *       - CustomHostPinnedMemAllocator
282	 *       - CustomCudaMemAllocator
283	 *
284	 * A `CustomMemAllocator` is passed as a constructor argument to `CustomAllocator`.
285	 *
286	 * @tparam AllocatorType  the type of the allocator (one of: HostMemAllocator, HostPinnedMemAllocator, CudaMemAllocator)
287	 */
288	template<typename AllocatorType>
289	class CustomMemAllocator
290	{
291	private:
292	    template<typename Callable>
293	    struct has_trivial_copy_and_destruction
294	        : std::integral_constant<bool, std::is_trivially_copyable<Callable>::value
295	                                           && std::is_trivially_destructible<Callable>::value>
296	    {
297	    };
298	
299	    template<typename Callable>
300	    struct by_value
301	        : std::integral_constant<bool, has_trivial_copy_and_destruction<Callable>::value
302	                                           && sizeof(Callable) <= sizeof(NVCVResourceContext)
303	                                           && alignof(Callable) <= alignof(NVCVResourceContext)>
304	    {
305	    };
306	
307	    template<typename T>
308	    static constexpr size_t DataSize()
309	    {
310	        return std::is_empty<T>::value ? 0 : sizeof(T);
311	    }
312	
313	    static NVCVMemoryBuffer ToMemoryBuffer(std::nullptr_t) noexcept
314	    {
315	        return nullptr;
316	    }
317	
318	    static NVCVMemoryBuffer ToMemoryBuffer(NVCVMemoryBuffer ptr) noexcept
319	    {
320	        return ptr;
321	    }
322	
323	    template<typename T>
324	    static NVCVMemoryBuffer ToMemoryBuffer(T *ptr) noexcept
325	    {
326	        return static_cast<NVCVMemoryBuffer>(static_cast<void *>(ptr));
327	    }
328	
329	public:
330	    /**  Constructs a custom memory allocator from a pair of alloc/free functions
331	     *
332	     * Usage:
333	     *
334	     * ```
335	     * nvcv::CustomHostMemAllocator alloc(
336	     *     [&alloc](int64_t size, int32_t align)
337	     *     {
338	     *         return alloc.allocate(size, align);
339	     *     },
340	     *     [&alloc](NVCVMemoryBuffer mem, int64_t size, int32_t align)
341	     *     {
342	     *         alloc.free(mem, size, align);
343	     *     });
344	     * ```
345	     *
346	     * @note When used with lambda functions, the user is responsible for ensuring
347	     *       that the allocator object doesn't outlive the variables captured by reference.
348	     */
349	    template<typename AllocFunction, typename FreeFunction,
350	             typename = detail::EnableIf_t<detail::IsInvocableR<void *, AllocFunction, int64_t, int32_t>::value>,
351	             typename
352	             = detail::EnableIf_t<detail::IsInvocableR<void, FreeFunction, NVCVMemoryBuffer, int64_t, int32_t>::value>>
353	    CustomMemAllocator(AllocFunction &&alloc, FreeFunction &&free);
354	
355	    // REVISIT(michalz): Add a way of constructing a custom allocator without using lambdas/captures, e.g.
356	    //                from an object that matches the allocator concept.
357	
358	    CustomMemAllocator(CustomMemAllocator &&other) noexcept
359	    {
360	        *this = std::move(other);
361	    }
362	
363	    ~CustomMemAllocator()
364	    {
365	        reset();
366	    }
367	
368	    bool needsCleanup() const noexcept
369	    {
370	        return m_data.cleanup != nullptr;
371	    }
372	
373	    /** Gets the underlying allocator descriptor.
374	     */
375	    const NVCVResourceAllocator &cdata() const &noexcept
376	    {
377	        return m_data;
378	    }
379	
380	    /** Removes the underlying allocator descriptor, passing the ownership to the caller.
381	     */
382	    NVCV_NODISCARD NVCVResourceAllocator release() noexcept
383	    {
384	        NVCVResourceAllocator ret = {};
385	        std::swap(ret, m_data);
386	        return ret;
387	    }
388	
389	    /** Replaces the currently owned descriptor with the one passed in the argument.
390	     *
391	     * The ownership of the descriptor is transfered to `CustomMemAllocator`.
392	     */
393	    void reset(NVCVResourceAllocator &&alloc) noexcept
394	    {
395	        reset();
396	        m_data = std::move(alloc);
397	        alloc  = {};
398	    }
399	
400	    /** Clears the allocator descriptor, performing cleanup, if necessary.
401	     */
402	    void reset() noexcept
403	    {
404	        NVCVResourceAllocator data = release();
405	        if (data.cleanup)
406	        {
407	            data.cleanup(data.ctx, &data);
408	        }
409	    }
410	
411	    /** Moves the descriptor from another CustomMemAllocator to this one.
412	     *
413	     * If the previously owned descriptor requries cleanup, it is performed.
414	     * After the call, `other` has its descriptor cleared.
415	     */
416	    CustomMemAllocator &operator=(CustomMemAllocator &&other) noexcept
417	    {
418	        reset(other.release());
419	        return *this;
420	    }
421	
422	private:
423	    template<typename...>
424	    friend class CustomAllocator;
425	
426	    template<typename AllocFunction, typename FreeFunction>
427	    void Construct(AllocFunction &&alloc, FreeFunction &&free, std::true_type);
428	
429	    template<typename AllocFunction, typename FreeFunction>
430	    void Construct(AllocFunction &&alloc, FreeFunction &&free, std::false_type);
431	
432	    template<typename AllocFunction, typename FreeFunction>
433	    void ConstructFromDuplicateValues(const AllocFunction &alloc, const FreeFunction &free, std::true_type);
434	
435	#if __cplusplus < 201703L
436	    template<typename AllocFunction, typename FreeFunction>
437	    void ConstructByOneValue(AllocFunction &&, FreeFunction &&, std::true_type, std::false_type)
438	    {
439	        assert(!"should never get here");
440	    }
441	#endif
442	
443	    NVCVResourceAllocator m_data{};
444	};
445	
446	using CustomHostMemAllocator       = CustomMemAllocator<HostMemAllocator>;
447	using CustomHostPinnedMemAllocator = CustomMemAllocator<HostPinnedMemAllocator>;
448	using CustomCudaMemAllocator       = CustomMemAllocator<CudaMemAllocator>;
449	
450	/** A helper clas for defining custom allocators.
451	 *
452	 * @note Direct use of this class is recommended only in C++ 17 and newer.
453	 *       For older standards, use CreateCustomAllocator function insted.
454	 *
455	 * This class aggregates custom resource allocators.
456	 *
457	 * @tparam ResourceAllocators
458	 */
459	template<typename... ResourceAllocators>
460	class CustomAllocator final : public Allocator
461	{
462	public:
463	    explicit CustomAllocator(ResourceAllocators &&...allocators);
464	
465	    CustomAllocator(const CustomAllocator &)            = delete;
466	    CustomAllocator &operator=(const CustomAllocator &) = delete;
467	
468	    CustomAllocator(CustomAllocator &&other) noexcept
469	        : Allocator(std::move(other))
470	    {
471	    }
472	
473	    CustomAllocator &operator=(CustomAllocator &&other) noexcept
474	    {
475	        Allocator::operator=(std::move(other));
476	        return *this;
477	    }
478	
479	    ~CustomAllocator()
480	    {
481	        preDestroy();
482	    }
483	
484	private:
485	    static constexpr bool kHasReferences
486	        = detail::Disjunction<detail::IsRefWrapper<detail::RemoveRef_t<ResourceAllocators>>...>::value;
487	
488	    template<bool hasReferences = kHasReferences>
489	    detail::EnableIf_t<hasReferences> preDestroy() // NOSONAR: this public header is validated with C++11.
490	    {
491	        if (this->reset() != 0)
492	            throw CustomAllocatorError(
493	                "The allocator context contains references. The handle must not outlive the context.");
494	    }
495	
496	    template<bool hasReferences = kHasReferences>
497	    detail::EnableIf_t<!hasReferences> preDestroy() noexcept // NOSONAR: keep overload pair C++11-compatible.
498	    {
499	        // No external references are held, so there is nothing to release early.
500	    }
501	};
502	
503	/** Constructs a `CustomAllocator` from a set of resource allocators.
504	 */
505	template<typename... ResourceAllocators>
506	CustomAllocator<ResourceAllocators...> CreateCustomAllocator(ResourceAllocators &&...allocators)
507	{
508	    return CustomAllocator<ResourceAllocators...>{std::forward<ResourceAllocators>(allocators)...};
509	}
510	
511	} // namespace nvcv
512	
513	#include "AllocatorImpl.hpp" // NOSONAR: inline definitions require the declarations above.
514	
515	#endif // NVCV_ALLOC_ALLOCATOR_HPP
