57	template<class T, class... ARGS>
58	std::unique_ptr<T> AllocHostObj(IAllocator &alloc, ARGS &&...args)
59	{
60	    NVCVMemoryBuffer arena = alloc.allocHostMem(sizeof(T), alignof(T));
61	    try
62	    {
63	        return std::unique_ptr<T>{new (arena) T{std::forward<ARGS>(args)...}};
64	    }
65	    catch (...)
66	    {
67	        alloc.freeHostMem(arena, sizeof(T), alignof(T));
68	        throw;
69	    }
70	}
