73	void FreeHostObj(IAllocator &alloc, T *ptr) noexcept
74	{
75	    if (ptr != nullptr)
76	    {
77	        ptr->~T();
78	        alloc.freeHostMem(reinterpret_cast<NVCVMemoryBuffer>(ptr), sizeof(T), alignof(T));
79	    }
80	}
