58	//////////////////////////////////////////////////////////////////////////////
59	// CustomMemAllocator
60	
61	template<typename AllocatorType>
62	template<typename AllocFunction, typename FreeFunction, typename, typename>
63	CustomMemAllocator<AllocatorType>::CustomMemAllocator(AllocFunction &&alloc, FreeFunction &&free)
64	{
65	    static_assert(!std::is_lvalue_reference<AllocFunction>::value && !std::is_lvalue_reference<FreeFunction>::value,
66	                  "The allocation and deallocation functions must not be L-Value references. Use std::ref "
67	                  "if a reference is required. Note that using references will place additional requirements "
68	                  "on the lifetime of the function objects.");
69	
70	    using T            = std::tuple<AllocFunction, FreeFunction>;
71	    const bool trivial = has_trivial_copy_and_destruction<AllocFunction>::value
72	                      && has_trivial_copy_and_destruction<FreeFunction>::value;
73	
74	    const bool tuple_by_value
75	        = trivial && sizeof(T) <= sizeof(NVCVResourceContext) && alignof(T) <= alignof(NVCVResourceContext);
76	
77	    const bool construct_from_one_value_if_equal = trivial && std::is_same<AllocFunction, FreeFunction>::value
78	                                                && by_value<AllocFunction>::value && by_value<FreeFunction>::value
79	                                                && sizeof(AllocFunction) == sizeof(FreeFunction);
80	
81	    // Can we fit the tuple inside a single pointer? If yes, go for it!
82	    if NVCV_IF_CONSTEXPR (tuple_by_value)
83	    {
84	        Construct(std::forward<AllocFunction>(alloc), std::forward<FreeFunction>(free),
85	                  std::integral_constant<bool, tuple_by_value>());
86	    }
87	    // Are the same-type callables trivial and do their context objects coincide? If yes, use that object.
88	    // Different callable types must not share bytes because that would interpret one object as another type.
89	    else if NVCV_IF_CONSTEXPR (construct_from_one_value_if_equal)
90	    {
91	        if (!std::memcmp(&alloc, &free, std::min(DataSize<AllocFunction>(), DataSize<FreeFunction>())))
92	            ConstructFromDuplicateValues(std::forward<AllocFunction>(alloc), std::forward<FreeFunction>(free),
93	                                         std::integral_constant<bool, construct_from_one_value_if_equal>());
94	        else
95	            Construct(std::forward<AllocFunction>(alloc), std::forward<FreeFunction>(free),
96	                      std::integral_constant<bool, tuple_by_value>());
97	    }
98	    // Back to square one - need to dynamically allocate the objects - we still have _one_ context object for two functions;
99	    // with std::function we'd end up dynamically allocating a pair of std::functions, each of which could dynamically allocate
100	    // - so we're still good; possibly down from 3 dynamic allocations to one
101	    else
102	    {
103	        Construct(std::forward<AllocFunction>(alloc), std::forward<FreeFunction>(free),
104	                  std::integral_constant<bool, tuple_by_value>());
105	    }
106	    m_data.resType = AllocatorType::kResourceType;
107	}
108	
109	template<typename AllocatorType>
110	template<typename AllocFunction, typename FreeFunction>
111	void CustomMemAllocator<AllocatorType>::Construct(AllocFunction &&alloc, FreeFunction &&free, std::true_type)
112	{
113	    struct T
114	    {
115	        AllocFunction alloc;
116	        FreeFunction  free;
117	    };
118	
119	    T ctx{std::forward<AllocFunction>(alloc), std::forward<FreeFunction>(free)};
120	    static_assert(sizeof(T) <= sizeof(NVCVResourceContext),
121	                  "Internal error - this should never be invoked with a type that large.");
122	
123	    m_data.res.mem.fnAlloc = [](NVCVResourceContext c, int64_t size, int32_t align) -> NVCVMemoryBuffer
124	    {
125	        auto  *target   = reinterpret_cast<T *>(&c);
126	        auto &&callable = target->alloc;
127	        return CustomMemAllocator<AllocatorType>::ToMemoryBuffer(callable(size, align));
128	    };
129	    m_data.res.mem.fnFree = [](NVCVResourceContext c, NVCVMemoryBuffer ptr, int64_t size, int32_t align)
130	    {
131	        auto  *target   = reinterpret_cast<T *>(&c);
132	        auto &&callable = target->free;
133	        callable(ptr, size, align);
134	    };
135	
136	    m_data.cleanup = nullptr;
137	
138	    if NVCV_IF_CONSTEXPR (!std::is_empty<T>::value)
139	        std::memcpy(&m_data.ctx, &ctx, DataSize<T>());
140	}
141	
142	template<typename AllocatorType>
143	template<typename AllocFunction, typename FreeFunction>
144	void CustomMemAllocator<AllocatorType>::Construct(AllocFunction &&alloc, FreeFunction &&free, std::false_type)
145	{
146	    using T      = std::tuple<AllocFunction, FreeFunction>;
147	    auto ctx     = detail::MakeUniqueObj<T>(std::forward<AllocFunction>(alloc), std::forward<FreeFunction>(free));
148	    auto cleanup = [](NVCVResourceContext ctx, NVCVResourceAllocator *) noexcept
149	    {
150	        detail::UniqueObj<T> storage(static_cast<T *>(static_cast<void *>(ctx)));
151	        (void)storage;
152	    };
153	
154	    m_data.res.mem.fnAlloc = [](NVCVResourceContext c, int64_t size, int32_t align) -> NVCVMemoryBuffer
155	    {
156	        auto *ctx = static_cast<T *>(static_cast<void *>(c));
157	        return CustomMemAllocator<AllocatorType>::ToMemoryBuffer(std::get<0>(*ctx)(size, align));
158	    };
159	    m_data.res.mem.fnFree = [](NVCVResourceContext c, NVCVMemoryBuffer ptr, int64_t size, int32_t align)
160	    {
161	        auto *ctx = static_cast<T *>(static_cast<void *>(c));
162	        std::get<1> (*ctx)(ptr, size, align);
163	    };
164	
165	    m_data.cleanup = cleanup;
166	    m_data.ctx     = static_cast<NVCVResourceContext>(static_cast<void *>(ctx.release()));
167	}
168	
169	template<typename AllocatorType>
170	template<typename AllocFunction, typename FreeFunction>
171	void CustomMemAllocator<AllocatorType>::ConstructFromDuplicateValues(const AllocFunction &alloc,
172	                                                                     const FreeFunction  &free, std::true_type)
173	{
174	    static_assert(std::is_trivially_copyable<AllocFunction>::value || std::is_empty<AllocFunction>::value,
175	                  "Internal error - should not pick this overload");
176	    static_assert(std::is_trivially_copyable<FreeFunction>::value || std::is_empty<FreeFunction>::value,
177	                  "Internal error - should not pick this overload");
178	    m_data.res.mem.fnAlloc = [](NVCVResourceContext c, int64_t size, int32_t align) -> NVCVMemoryBuffer
179	    {
180	        auto *alloc = reinterpret_cast<AllocFunction *>(&c);
181	        return CustomMemAllocator<AllocatorType>::ToMemoryBuffer((*alloc)(size, align));
182	    };
183	    m_data.res.mem.fnFree = [](NVCVResourceContext c, NVCVMemoryBuffer ptr, int64_t size, int32_t align)
184	    {
185	        auto *free = reinterpret_cast<FreeFunction *>(&c);
186	        (*free)(ptr, size, align);
187	    };
188	
189	    m_data.cleanup = nullptr;
190	    m_data.ctx     = nullptr;
191	    if (DataSize<AllocFunction>() >= DataSize<FreeFunction>())
192	        std::memcpy(&m_data.ctx, &alloc, DataSize<AllocFunction>());
193	    else
194	        std::memcpy(&m_data.ctx, &free, DataSize<FreeFunction>());
195	}
196	
197	//////////////////////////////////////////////////////////////////////////////
198	// CustomAllocator
199	
200	template<typename... ResourceAllocators>
201	inline CustomAllocator<ResourceAllocators...>::CustomAllocator(ResourceAllocators &&...allocators)
202	{
203	    std::array<NVCVResourceAllocator, sizeof...(allocators)> data = {allocators.cdata()...};
204	    NVCVAllocatorHandle                                      h    = {};
205	    detail::CheckThrow(nvcvAllocatorConstructCustom(data.data(), static_cast<int32_t>(data.size()), &h));
206	    // void-cast the (nodiscard) result of the allocators - we know what we're doing here...
207	    (void)std::initializer_list<int>{((void)allocators.release(), 0)...};
208	    reset(std::move(h));
209	}
210	
211	namespace detail {
212	
213	template<NVCVResourceType KIND>
214	MemAllocatorWithKind<KIND>::MemAllocatorWithKind(const NVCVResourceAllocator &data)
215	    : MemAllocator(data)
216	{
217	    if (!IsCompatibleKind(data.resType))
218	    {
219	        throw Exception(Status::ERROR_INVALID_ARGUMENT, "Incompatible allocated resource type.");
220	    }
221	}
222	} // namespace detail
223	
224	} // namespace nvcv
