            if (reqs == nullptr)
            {
                throw priv::Exception(NVCV_ERROR_INVALID_ARGUMENT, "Pointer to output requirements must not be NULL");
            }

            priv::DataType type{dtype};

            *reqs = priv::Tensor::CalcRequirements(rank, shape, type, layout, baseAlign, rowAlign);
        });
}

